    JSONObject decoderSurfaceLuma()throws Exception {
        assertTrue("Surface diagnostic is restricted to the dedicated emulator",android.os.Build.HARDWARE.equals("ranchu")||android.os.Build.HARDWARE.equals("goldfish"));
        Field owner=Game.class.getDeclaredField("decoderRenderer");owner.setAccessible(true);Object renderer=owner.get(game);Field value=renderer.getClass().getDeclaredField("videoDecoder");value.setAccessible(true);android.media.MediaCodec codec=(android.media.MediaCodec)value.get(renderer);android.media.MediaFormat format=codec.getOutputFormat();
        int width=format.getInteger(android.media.MediaFormat.KEY_WIDTH),height=format.getInteger(android.media.MediaFormat.KEY_HEIGHT);assertTrue(width>0&&height>0&&width<=4096&&height<=4096);SurfaceView[] original={null};instrument.runOnMainSync(()->original[0]=game.findViewById(R.id.surfaceView));
        android.media.ImageReader reader=android.media.ImageReader.newInstance(width,height,ImageFormat.YUV_420_888,2);android.os.HandlerThread worker=new android.os.HandlerThread("Own decoder luma diagnostic");worker.start();CountDownLatch samples=new CountDownLatch(2);long[] values=new long[4];JSONObject report=RhActions.obj("diagnosticSurfaceChange",true,"outputFormat",format.toString());
        reader.setOnImageAvailableListener(source->{try(android.media.Image image=source.acquireLatestImage()){if(image==null)return;android.media.Image.Plane y=image.getPlanes()[0];java.nio.ByteBuffer bytes=y.getBuffer();Rect crop=image.getCropRect();synchronized(values){values[0]++;for(int row=crop.top;row<crop.bottom;row+=16)for(int col=crop.left;col<crop.right;col+=16){int luma=bytes.get(row*y.getRowStride()+col*y.getPixelStride())&255;values[1]++;values[2]+=luma;if(luma>40)values[3]++;}}samples.countDown();}catch(Exception failure){synchronized(values){try{report.put("imageError",failure.toString());}catch(JSONException ignored){}}samples.countDown();}},new android.os.Handler(worker.getLooper()));
        boolean changed=false;
        try{codec.setOutputSurface(reader.getSurface());changed=true;report.put("receivedTwoImages",samples.await(5,TimeUnit.SECONDS));}
        catch(Exception failure){report.put("error",failure.toString());}
        finally{try{if(changed){codec.setOutputSurface(original[0].getHolder().getSurface());report.put("originalSurfaceRestored",true);}}finally{reader.close();worker.quitSafely();worker.join(2000);}}
        synchronized(values){report.put("frames",values[0]).put("samples",values[1]).put("meanY",values[1]==0?0:(double)values[2]/values[1]).put("nonDark",values[3]);}return report;
    }
    JSONObject videoPixels(String name)throws Exception{
        SurfaceView[] surface={null};instrument.runOnMainSync(()->surface[0]=game.findViewById(R.id.surfaceView));assertNotNull(surface[0]);Bitmap bitmap=Bitmap.createBitmap(surface[0].getWidth(),surface[0].getHeight(),Bitmap.Config.ARGB_8888);int[] result={-1};int samples=0,nonDark=0,attempts=0;long begin=System.nanoTime(),end=begin+TimeUnit.SECONDS.toNanos(6);
        try{do{CountDownLatch done=new CountDownLatch(1);instrument.runOnMainSync(()->PixelCopy.request(surface[0],bitmap,code->{result[0]=code;done.countDown();},new android.os.Handler(android.os.Looper.getMainLooper())));assertTrue(done.await(3,TimeUnit.SECONDS));samples=nonDark=0;attempts++;if(result[0]==PixelCopy.SUCCESS){for(int y=0;y<bitmap.getHeight();y+=8)for(int x=0;x<bitmap.getWidth();x+=8){int pixel=bitmap.getPixel(x,y);samples++;if(Color.red(pixel)>24||Color.green(pixel)>24||Color.blue(pixel)>24)nonDark++;}}if(samples>0&&nonDark>samples/100)break;Thread.sleep(100);}while(System.nanoTime()<end);if(result[0]==PixelCopy.SUCCESS)try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}return RhActions.obj("pixelCopyResult",result[0],"samples",samples,"nonDark",nonDark,"visibleContent",samples>0&&nonDark>samples/100,"attempts",attempts,"elapsedMs",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-begin));}finally{bitmap.recycle();}
    }
